**行号：L33–L130**

### 代码原文
```ts
  33  /** 消息里的 @ 提及。 */
  34  export interface ChannelMention {
  35    /** 原始文本占位符（例如 @_user_1）。 */
  36    token?: string;
  37    /** 平台原始被 @ 用户 ID。 */
  38    id: string;
  39    /** 平台或配置解析出来的名字。 */
  40    name?: string;
  41    /** 经可信配置映射到的目标机器人名列表。 */
  42    botNames: string[];
  43  }
  44  
  45  
  46  /** 渠道收到的原始附件描述（落在渠道目录，不直接指向任意本机路径）。 */
  47  export interface ChannelAttachment {
  48    /** 附件稳定标识。 */
  49    id: string;
  50    /** 原始或清洗前的展示文件名。 */
  51    name: string;
  52    /** MIME 类型（可用时）。 */
  53    mime?: string;
  54    /** 字节大小（可用时）。 */
  55    size?: number;
  56    /** 渠道侧落盘引用路径（内部物化使用，历史工具不对外暴露本机路径）。 */
  57    sourceRef: string;
  58    /** 渠道下载是否成功。 */
  59    state: 'available' | 'unavailable';
  60    /** 下载失败原因。 */
  61    reason?: string;
  62  }
  63  
  64  
  65  /** 原始引用消息指向。 */
  66  export interface ChannelReplyTo {
  67    /** 标准 messageId（可用时）。 */
  68    messageId?: string;
  69    /** 平台原始消息 ID。 */
  70    nativeId?: string;
  71  }
  72  
  73  
  74  /** 不可变的来源兼容地址。 */
  75  export interface ChannelOrigin {
  76    /** 渠道名（feishu / wechat / http / cli）。 */
  77    channel: string;
  78    /** 深拷贝的原渠道地址对象。 */
  79    address: Record<string, unknown>;
  80  }
  81  
  82  
  83  /** 来源可见域与授权范围。 */
  84  export interface ChannelVisibility {
  85    /** 作用域字符串描述。 */
  86    scope: string;
  87    /** 是否受信任作用域（如私聊或 trusted 群）。 */
  88    trusted: boolean;
  89    /** 显式配置的公共源白名单。 */
  90    publicSourceIds: string[];
  91  }
  92  
  93  
  94  /** 单机器人路由附带信息。 */
  95  export interface BotRoutingHint {
  96    /** 该机器人在这条消息上是否仅监听当背景。 */
  97    listenOnly: boolean;
  98    /** 是否由决策模型判断是否接话。 */
  99    judge?: boolean;
 100  }
 101  
 102  
 103  /** 渠道路由建议。 */
 104  export interface ChannelRouting {
 105    /** 默认是否仅监听当背景。 */
 106    listenOnly: boolean;
 107    /** 默认是否由决策模型判断。 */
 108    judge?: boolean;
 109    /** 服务端校验过的指定会话号：bots 只投给这场会话的机器人、进这场会话（网页“发给哪个会话”、引用别的渠道的消息）。 */
 110    sessionId?: string;
 111    /** 引用别的渠道的消息时，被引那条的原渠道、原机器人、原会话（入口校验过）；只作记录，回话照旧回本条来源。 */
 112    replyOrigin?: { source: string; bot: string; sessionId: string };
 113    /** 一轮一次 channel_reply 都没调时，把最后的话当 final 直接发出去（一对一的渠道：网页、命令行、微信）；不写走修复轮。 */
 114    autoFinal?: boolean;
 115    /** 多机器人场景下每个机器人各自的监听/判断覆盖项。 */
 116    byBot?: Record<string, BotRoutingHint>;
 117  }
 118  
 119  
 120  /** 网页发话时附带的当前查看上下文（供 131 接入 POST /api/message 的 view 后填入）。 */
 121  export interface ChannelView {
 122    /** 网页当前正在查看的渠道名（feishu / wechat / http / cli）。 */
 123    channel: string;
 124    /** 网页当前正在查看的聊天标识；看的是整个渠道时是 ''。 */
 125    chat: string;
 126    /** 给人看的名字（web-api 照 /api/channels 的清单填）：“飞书·群·测试群”“飞书·全部聊天”；前台这一轮的提示里用它。 */
 127    label?: string;
 128  }
 129  
 130  
```

### 解释
- 都是纯类型，按声明顺序拆成八个子块。

