 626  export function encodeHistoryCursor(payload: HistoryCursorPayload): string {
 627    const raw = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url');
 628    const sig = crypto.createHmac('sha256', CURSOR_SECRET).update(raw).digest('base64url');
