 802  export async function requestChannelReply(
 803    ctx: cordis.Context,
 804    req: Omit<ChannelReplyRequest, 'requestId'>,
 805    timeoutMs = 30_000,
 806  ): Promise<ReplyReceipt> {
 807    const requestId = `rep_${crypto.randomUUID()}`;
 808    const fullRequest: ChannelReplyRequest = { ...req, requestId };
 809  
 810    return await new Promise<ReplyReceipt>((resolve) => {
 811      let settled = false;
 812      let timer: ReturnType<typeof setTimeout> | undefined;
 813      let dispose: () => void = () => undefined;
 814  
 815      const finish = (receipt: ReplyReceipt): void => {
 816        if (settled) return;
 817        settled = true;
 818        if (timer !== undefined) clearTimeout(timer);
 819        dispose();
 820        resolve(receipt);
 821      };
 822  
 823      //M 监听匹配本请求 requestId 的渠道回执事件，收到后第一时间收口并返回回执。
 824      dispose = ctx.on('channel/replied', (event) => {
 825        if (event.requestId !== requestId) return;
 826        //M 收到匹配的发送回执后立即结束等待。
 827        finish(event.receipt);
 828      });
 829  
 830      //G 超过约定等待时间仍未收到回执时，返回 uncertain 状态，绝不伪造成功回执。
 831      timer = setTimeout(() => {
 832        finish({
 833          v: 2,
 834          ok: false,
 835          status: 'uncertain',
 836          replyRequestKey: req.replyRequestKey,
 837          replyRoundKey: req.replyRoundKey,
 838          replyIndex: req.replyIndex,
 839          kind: req.kind,
 840          parts: req.parts.map((part) => ({
 841            partId: part.partId,
 842            kind: part.kind,
 843            status: 'uncertain',
 844            reason: '等待渠道发送回执超时',
 845          })),
 846          reason: '等待渠道发送回执超时',
 847          at: Date.now(),
 848        });
 849      }, timeoutMs);
 850  
 851      //M 串行通知渠道插件投递回复；无人接单时立回 rejected，抛错时回 uncertain。
 852      void ctx.serial('channel/reply', fullRequest).then(() => {
 853        if (settled) return;
 854        if (fullRequest.handled === true) return;
 855  
 856        //G 没有任何渠道接单时直接回报明确原因，不伪造发送成功。
