 868            kind: part.kind,
 869            status: 'rejected',
 870            reason: unhandledReason,
 871          })),
 872          reason: unhandledReason,
 873          at: Date.now(),
 874        });
 875      }).catch((error: unknown) => {
 876        let reason = String(error);
 877        if (error instanceof Error) {
 878          reason = error.message;
 879        }
 880        //M 派发异常无法确认对方是否收到，统一以 uncertain 状态收口。
